properties.Script_1:
// ------------------------------------------------------
// Generar registros de log de sesión en tabla en memoria
// ------------------------------------------------------

// Se abre transacción si no existe
transCurso = theRoot.existTrans();
if (transCurso == false)
	transNueva = theRoot.beginTrans("Generando log de sesión en memoria");

// Si hay transacción se generan los registros
if (transCurso || transNueva)
{
	// Creamos el registro de la tabla de log de sesión en memoria 
	var registro = new VRegister(theRoot);
	registro.setTable("sygemat_corralon_dat/LOG_SES_W");

	// Recorremos el objeto JSON con los registros del log
	var log        = "[" + theRegisterIn.fieldToString("LOG") + "]";
	var jsonObject = eval('(' + log + ')');

	for(var index in jsonObject)
	{
		registro.setField("FCH"        , jsonObject[index].fecha);
		registro.setField("HOR"        , jsonObject[index].hora);
		registro.setField("OBJ_TIP_ID" , jsonObject[index].tipo_id);
		registro.setField("OBJ_TIP_NOM", jsonObject[index].tipo_name);
		registro.setField("OBJ_NOM"    , jsonObject[index].objeto_name);
		registro.setField("OBJ_ID_REF" , jsonObject[index].objeto_idref);
		registro.setField("REG_ID"     , jsonObject[index].id);
		registro.setField("REG_NOM"    , jsonObject[index].name);

		registro.addRegister();
	}

	// Se cierra la transacción si se creó una nueva
	if (transCurso == false)
		theRoot.commitTrans();
};
